	vl::Ptr<WfType> AstVisitor::CopyNode(WfType* node)
	{
		if (!node) return nullptr;
		node->Accept(static_cast<WfType::IVisitor*>(this));
		this->result->codeRange = node->codeRange;
		return this->result.Cast<WfType>();
	}

